INSERT INTO `wp_postmeta` VALUES (3051,925,'_content_sections_0_section_heading','field_6a467853f47df');
INSERT INTO `wp_postmeta` VALUES (3052,925,'content_sections_0_section_content','<h2 class=\"PDq2pG_selectionAnchorContainer\" data-section-id=\"5veygf\" data-start=\"793\" data-end=\"827\"><span style=\"color: #00467b;\">What is the Cancun Airport FBO?</span></h2>\r\n<p data-start=\"829\" data-end=\"1058\">The Cancun Airport <a href=\"https://share.google/22a4sLJrdXfn2HY5P\">FBO (Fixed Base Operator)</a> is the private aviation terminal at Cancun International Airport. Unlike the commercial terminals (T2, T3 and T4), the FBO is exclusively used for private aircraft and charter flights.</p>\r\n<p data-start=\"1060\" data-end=\"1304\">Flights Holbox operates all private flights to Holbox from this terminal, providing a fast, comfortable and exclusive travel experience. Passengers avoid the busy commercial terminals and enjoy a private check-in before boarding their aircraft.</p>\r\n<p data-start=\"1306\" data-end=\"1421\">The flight from Cancun to Holbox takes approximately <strong data-start=\"1359\" data-end=\"1373\">30 minutes</strong>, making it the fastest way to reach the island.</p>');
INSERT INTO `wp_postmeta` VALUES (3053,925,'_content_sections_0_section_content','field_6a46785cf47e0');
INSERT INTO `wp_postmeta` VALUES (3054,925,'content_sections_1_section_heading','Location Private Terminal Cancun FBO');
INSERT INTO `wp_postmeta` VALUES (3055,925,'_content_sections_1_section_heading','field_6a467853f47df');
INSERT INTO `wp_postmeta` VALUES (3056,925,'content_sections_1_section_content','&nbsp;\r\n<h2 class=\"PDq2pG_selectionAnchorContainer\" data-section-id=\"5veygf\" data-start=\"793\" data-end=\"827\"><span style=\"color: #00467b;\">Where is the private terminal in Cancun located?</span></h2>\r\n<ul>\r\n 	<li>Located inside Cancun International Airport</li>\r\n 	<li data-section-id=\"47lfql\" data-start=\"1527\" data-end=\"1562\">Separate from Terminal 2, 3 and 4</li>\r\n 	<li data-section-id=\"7tmiah\" data-start=\"1563\" data-end=\"1588\">Only accessible by road</li>\r\n 	<li data-section-id=\"1qu0oce\" data-start=\"1589\" data-end=\"1624\">Taxi or private transfer required</li>\r\n 	<li data-section-id=\"1w9l0ny\" data-start=\"1625\" data-end=\"1651\">Not connected by shuttle</li>\r\n 	<li data-section-id=\"1w9l0ny\" data-start=\"1625\" data-end=\"1651\"><strong>Find the exact Location on google maps <a href=\"https://share.google/22a4sLJrdXfn2HY5P\">here</a></strong></li>\r\n</ul>');
INSERT INTO `wp_postmeta` VALUES (3057,925,'_content_sections_1_section_content','field_6a46785cf47e0');
INSERT INTO `wp_postmeta` VALUES (3058,925,'content_sections_2_section_heading','How To Get To The Private Terminal in Cancun');
INSERT INTO `wp_postmeta` VALUES (3059,925,'_content_sections_2_section_heading','field_6a467853f47df');
INSERT INTO `wp_postmeta` VALUES (3060,925,'content_sections_2_section_content','<h2 class=\"PDq2pG_selectionAnchorContainer\" data-section-id=\"5veygf\" data-start=\"793\" data-end=\"827\"><span style=\"color: #00467b;\">How do i get to the private Terminal in Cancun?</span></h2>\r\n<h3>From Cancun international Airport, Terminal 2, 3 and 4</h3>\r\n<p data-start=\"1868\" data-end=\"1903\">If arriving on a commercial flight:</p>\r\n\r\n<ul data-start=\"1905\" data-end=\"2030\">\r\n 	<li data-section-id=\"7po1z1\" data-start=\"1905\" data-end=\"1925\">Exit your terminal</li>\r\n 	<li data-section-id=\"1rw1hg5\" data-start=\"1926\" data-end=\"1959\">Take an authorised airport taxi, we can help you setting up your transfer</li>\r\n 	<li data-section-id=\"1djyukp\" data-start=\"1960\" data-end=\"1998\">Taxi ride approximately 5–10 minutes</li>\r\n 	<li data-section-id=\"lnzntz\" data-start=\"1999\" data-end=\"2030\">Cost approximately <strong data-start=\"2020\" data-end=\"2030\">30 USD</strong></li>\r\n 	<li data-section-id=\"lnzntz\" data-start=\"1999\" data-end=\"2030\">you can not walk between the international terminal and the private terminal</li>\r\n</ul>\r\n<h3>From Cancun Center or any other location</h3>\r\n<ul>\r\n 	<li>Take an authorised  taxi, we can help you setting up your transfer</li>\r\n 	<li>contact<span style=\"color: #e6af2a;\"><a style=\"color: #e6af2a;\" href=\"https://goholboxtransfers.com/\"> Go Holbox Transfers</a> </span>for a safe transfer service</li>\r\n</ul>\r\n<h3>Airport Fee</h3>\r\n<strong data-start=\"471\" data-end=\"497\">Airport Use Fee (TUA):</strong> Passengers departing on domestic private charter flights from the <strong data-start=\"564\" data-end=\"600\">Cancun FBO (Fixed Base Operator)</strong> are required to pay an <strong data-start=\"624\" data-end=\"675\">Airport Use Fee (TUA) of MXN $200 per passenger</strong>. This fee is <strong data-start=\"689\" data-end=\"705\">not included</strong> in the charter price and is payable before departure.\r\n\r\n&nbsp;');
INSERT INTO `wp_postmeta` VALUES (3061,925,'_content_sections_2_section_content','field_6a46785cf47e0');
INSERT INTO `wp_postmeta` VALUES (3062,925,'content_sections_3_section_heading','Example for style maybe we can create something simular?');
INSERT INTO `wp_postmeta` VALUES (3063,925,'_content_sections_3_section_heading','field_6a467853f47df');
INSERT INTO `wp_postmeta` VALUES (3064,925,'content_sections_3_section_content','<div style=\"max-width: 820px; margin: 35px auto; font-family: Arial,sans-serif;\">\r\n\r\n<!-- Intro Card -->\r\n<div style=\"background: #FAFBFD; border-left: 4px solid #004280; border-radius: 10px; box-shadow: 0 6px 18px rgba(0,0,0,.06); padding: 28px; margin-bottom: 24px;\">\r\n<h2 style=\"margin: 0 0 15px; color: #004280; font-size: 28px; font-weight: bold; line-height: 1.3;\">Cancun Airport FBO Information</h2>\r\n<p style=\"margin: 0; color: #555555; line-height: 1.8;\">Flights Holbox operates private flights to Holbox from the Cancun Airport FBO. This private terminal offers a quieter and more comfortable departure experience away from the busy commercial terminals.</p>\r\n\r\n</div>\r\n<!-- Card 1 -->\r\n<div style=\"background: #FAFBFD; border-left: 4px solid #004280; border-radius: 10px; box-shadow: 0 6px 18px rgba(0,0,0,.06); padding: 28px; margin-bottom: 24px;\">\r\n<h2 style=\"margin: 0 0 15px; color: #004280; font-size: 28px; font-weight: bold; line-height: 1.3;\">What Is the Cancun Airport FBO?</h2>\r\n<p style=\"margin: 0; color: #555555; line-height: 1.8;\">The Cancun Airport FBO, or Fixed Base Operator, is the private aviation terminal at Cancun International Airport. Unlike the commercial terminals, Terminal 2, Terminal 3 and Terminal 4, the FBO is used exclusively for private aircraft and charter flights.</p>\r\n\r\n</div>\r\n<!-- Card 2 -->\r\n<div style=\"background: #FAFBFD; border-left: 4px solid #004280; border-radius: 10px; box-shadow: 0 6px 18px rgba(0,0,0,.06); padding: 28px; margin-bottom: 24px;\">\r\n<h2 style=\"margin: 0 0 15px; color: #004280; font-size: 28px; font-weight: bold; line-height: 1.3;\">Where Is the Private Terminal in Cancun Located?</h2>\r\n<p style=\"margin: 0 0 15px; color: #555555; line-height: 1.8;\">The private terminal is located inside the grounds of Cancun International Airport. However, it is separate from Terminal 2, Terminal 3 and Terminal 4.</p>\r\n<p style=\"margin: 0; color: #555555; line-height: 1.8;\">The FBO is only accessible by road and is not connected to the commercial terminals by a pedestrian walkway or airport shuttle.</p>\r\n\r\n</div>\r\n<!-- Card 3 -->\r\n<div style=\"background: #FAFBFD; border-left: 4px solid #004280; border-radius: 10px; box-shadow: 0 6px 18px rgba(0,0,0,.06); padding: 28px; margin-bottom: 24px;\">\r\n<h2 style=\"margin: 0 0 15px; color: #004280; font-size: 28px; font-weight: bold; line-height: 1.3;\">How Do I Get to the Private Terminal in Cancun?</h2>\r\n<p style=\"margin: 0 0 16px; color: #555555; line-height: 1.8;\">When arriving on a commercial flight at Terminal 2, Terminal 3 or Terminal 4, you will need to take an authorised airport taxi or a pre-arranged private transfer to the FBO.</p>\r\n\r\n<div style=\"background: #ffffff; border: 1px solid #E6EAF0; border-radius: 8px; padding: 20px; margin: 18px 0;\">\r\n<p style=\"margin: 0 0 10px; color: #555555; line-height: 1.7;\"><strong style=\"color: #004280;\">Travel time:</strong> Approximately 5–10 minutes</p>\r\n<p style=\"margin: 0 0 10px; color: #555555; line-height: 1.7;\"><strong style=\"color: #004280;\">Estimated taxi cost:</strong> Approximately USD 30</p>\r\n<p style=\"margin: 0 0 10px; color: #555555; line-height: 1.7;\"><strong style=\"color: #004280;\">Walking:</strong> It is not possible to walk between the commercial terminals and the FBO</p>\r\n<p style=\"margin: 0; color: #555555; line-height: 1.7;\"><strong style=\"color: #004280;\">Airport shuttle:</strong> There is no shuttle connection to the private terminal</p>\r\n\r\n</div>\r\n<p style=\"margin: 0; color: #555555; line-height: 1.8;\">Flights Holbox can help arrange your transfer from the commercial terminal to the Cancun Airport FBO.</p>\r\n\r\n</div>\r\n<!-- Card 4 -->\r\n<div style=\"background: #FAFBFD; border-left: 4px solid #004280; border-radius: 10px; box-shadow: 0 6px 18px rgba(0,0,0,.06); padding: 28px; margin-bottom: 24px;\">\r\n<h2 style=\"margin: 0 0 15px; color: #004280; font-size: 28px; font-weight: bold; line-height: 1.3;\">Private Flights from Cancun to Holbox</h2>\r\n<p style=\"margin: 0 0 15px; color: #555555; line-height: 1.8;\">Flights Holbox operates private flights to Holbox from this terminal, providing a fast, comfortable and exclusive travel experience. Passengers avoid the busy commercial departure areas and complete a private check-in before boarding their aircraft.</p>\r\n<p style=\"margin: 0; color: #555555; line-height: 1.8;\">The flight from Cancun to Holbox takes approximately 30 minutes, making a private flight the fastest way to reach Holbox Island.</p>\r\n\r\n</div>\r\n<!-- Location Card -->\r\n<div style=\"background: #ffffff; border: 2px solid #F4A000; border-radius: 10px; box-shadow: 0 6px 18px rgba(0,0,0,.06); padding: 28px; margin-bottom: 24px;\">\r\n<h2 style=\"margin: 0 0 15px; color: #004280; font-size: 28px; font-weight: bold; line-height: 1.3;\">Cancun Airport FBO Location</h2>\r\n<p style=\"margin: 0 0 20px; color: #555555; line-height: 1.8;\">Open the exact location of the private terminal in Google Maps before travelling to the airport.</p>\r\n<a style=\"display: inline-block; background: #F4A000; color: #ffffff; text-decoration: none; padding: 14px 24px; border-radius: 7px; font-weight: bold;\" href=\"https://share.google/Ppszco55ELgwR5j6p\" target=\"_blank\" rel=\"noopener noreferrer\">\r\nView the FBO on Google Maps\r\n</a>\r\n\r\n</div>\r\n<!-- CTA Card -->\r\n<div style=\"background: linear-gradient(135deg,#004280 0%,#0058A8 100%); border-radius: 10px; box-shadow: 0 6px 18px rgba(0,0,0,.08); padding: 30px; text-align: center;\">\r\n<h2 style=\"margin: 0 0 14px; color: #ffffff; font-size: 28px; font-weight: bold; line-height: 1.3;\">Book Your Private Flight to Holbox</h2>\r\n<p style=\"margin: 0 0 22px; color: #ffffff; line-height: 1.8;\">Contact Flights Holbox to request availability and arrange your private flight from Cancun to Holbox.</p>\r\n<a style=\"display: inline-block; background: #F4A000; color: #ffffff; text-decoration: none; padding: 14px 26px; border-radius: 7px; font-weight: bold;\" href=\"https://flightsholboxv1.local/contact-us/\">\r\nRequest a Flight\r\n</a>\r\n\r\n</div>\r\n</div>');
