",\"_slider_items_4_button_button_colour\":\"field_69fb154a3681d\",\"slider_items_4_button\":\"\",\"_slider_items_4_button\":\"field_6a47bb3fb3701\",\"slider_items_5_slide_post\":220,\"_slider_items_5_slide_post\":\"field_6a47ba81b3700\",\"slider_items_5_button_button_link\":{\"title\":\"Read More\",\"url\":\"https://flightsholboxv1.local/airports/cozumel-airport-fbo/\",\"target\":\"\"},\"_slider_items_5_button_button_link\":\"field_6a10337e94d01\",\"slider_items_5_button_button_colour\":\"white\",\"_slider_items_5_button_button_colour\":\"field_69fb154a3681d\",\"slider_items_5_button\":\"\",\"_slider_items_5_button\":\"field_6a47bb3fb3701\",\"slider_items\":6,\"_slider_items\":\"field_6a47ba6db36ff\",\"background_colour\":\"white\",\"_background_colour\":\"field_69fb291d7099f\",\"container_size\":\"small\",\"_container_size\":\"field_6a104fa067637\",\"panel_settings\":\"\",\"_panel_settings\":\"field_6a47bb6507269\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/testimonial-panel {\"name\":\"acf/testimonial-panel\",\"data\":{\"embed_code\":\"[grw id=90]\",\"_embed_code\":\"field_6a4673a18eb19\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/social-panel {\"name\":\"acf/social-panel\",\"data\":{\"platform\":\"tripadvisor\",\"_platform\":\"field_6a57946f95a8a\",\"button_link_button_link\":{\"title\":\"Reviews Tripadvisor\",\"url\":\"https://www.tripadvisor.co.uk/Attraction_Review-g616319-d12454502-Reviews-Flights_Holbox-Holbox_Island_Yucatan_Peninsula.html\",\"target\":\"\"},\"_button_link_button_link\":\"field_6a10337e94d01\",\"button_link_button_colour\":\"gold\",\"_button_link_button_colour\":\"field_69fb154a3681d\",\"button_link\":\"\",\"_button_link\":\"field_6a4eb972d02cd\",\"background_colour\":\"\",\"_background_colour\":\"field_69fb291d7099f\",\"container_size\":\"\",\"_container_size\":\"field_6a104fa067637\",\"panel_settings\":\"\",\"_panel_settings\":\"field_6a4eb99ed02ce\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/text-panel {\"name\":\"acf/text-panel\",\"data\":{\"content\":\"\\u003ch2 class=\\u0022PDq2pG_selectionAnchorContainer\\u0022 style=\\u0022text-align: center;\\u0022 data-section-id=\\u00222kcj8n\\u0022 data-start=\\u00221349\\u0022 data-end=\\u00221393\\u0022\\u003e\\u003cspan style=\\u0022color: #00467b;\\u0022\\u003eReady to Experience Holbox From the Sky?\\u003c/span\\u003e\\u003c/h2\\u003e\\r\\n\\u003cp style=\\u0022text-align: center;\\u0022 data-start=\\u00221395\\u0022 data-end=\\u00221516\\u0022\\u003e\\u003cem data-start=\\u00221395\\u0022 data-end=\\u00221516\\u0022\\u003eSkip the long drive and ferry. Fly directly to Holbox in approximately 30 minutes aboard your private charter aircraft.\\u003c/em\\u003e\\u003c/p\\u003e\",\"_content\":\"field_6a465ad18514f\",\"text_alignment\":\"center\",\"_text_alignment\":\"field_6a47a299896e2\",\"background_colour\":\"\",\"_background_colour\":\"field_69fb291d7099f\",\"container_size\":\"\",\"_container_size\":\"field_6a104fa067637\",\"panel_settings\":\"\",\"_panel_settings\":\"field_6a47a682138e0\"},\"mode\":\"edit\"} /-->\n\n<!-- wp:acf/feature-panel {\"name\":\"acf/feature-panel\",\"data\":{\"features_0_feature_image\":84,\"_features_0_feature_image\":\"field_6a4671cfe41e3\",\"features_0_feature_heading\":\"Ready to Fly?\",\"_features_0_feature_heading\":\"field_6a4671dbe41e4\",\"features_0_button_button_link\":{\"title\":\"Click Here\",\"url\":\"https://flightsholboxv1.local/\",\"target\":\"\"},\"_features_0_button_button_link\":\"field_6a10337e94d01\",\"features_0_button_button_colour\":\"gold\",\"_features_0_button_button_colour\":\"field_69fb154a3681d\",\"features_0_button\":\"\",\"_features_0_button\":\"field_6a4671e6e41e5\",\"features_1_feature_image\":975,\"_features_1_feature_image\":\"field_6a4671cfe41e3\",\"features_1_feature_heading\":\"Need More Help?\",\"_features_1_feature_heading\":\"field_6a4671dbe41e4\",\"features_1_button_button_link\":{\"title\":\"Contact Us\",\"url\":\"https://flightsholboxv1.local/contact-us/\",\"target\":\"\"},\"_features_1_butto